// Populate data from last Car Repair Request
function populate_from_last_repair(frm) {
    frappe.db.get_list("Car Repair Request", {
        filters: { "customer_name": frm.doc.customer_name },
        fields: ["name", "car", "car_model", "license_plate", "email", "chassis_no", "phone", "repair_request_date", "priority"],
        order_by: "creation desc",
        limit_page_length: 1
    }).then(requests => {
        if (requests && requests.length) {
            const req = requests[0];

            frm.set_value("car", req.car);
            frm.set_value("model", req.car_model);
            frm.set_value("license_plate", req.license_plate);
            frm.set_value("chassis_no", req.chassis_no);
            frm.set_value("email_id", req.email);
            frm.set_value("phone", req.phone);
            frm.set_value("date_of_receipt", req.repair_request_date);

            if (req.priority) {
                let field = frm.get_field("priority");
                if (!field.df.options.includes(req.priority)) {
                    field.df.options += `\n${req.priority}`;
                    field.refresh();
                }
                frm.set_value("priority", req.priority);
            }

            // Fetch full Car Repair Request to get child table images
            frappe.db.get_doc("Car Repair Request", req.name).then(doc => {
                if (doc.car_repair_images && doc.car_repair_images.length) {
                    frm.clear_table("car_repair_images");
                    doc.car_repair_images.forEach(img => {
                        let row = frm.add_child("car_repair_images");
                        row.image = img.image;
                    });
                    frm.refresh_field("car_repair_images");

                    make_images_clickable(frm);
                }
            });

            make_fields_readonly(frm);
        }
    });
}

// Make main form fields read-only
function make_fields_readonly(frm) {
    const readonly_fields = [
        "car",
        "model",
        "license_plate",
        "chassis_no",
        "email_id",
        "phone",
        "date_of_receipt",
        "priority",
        "customer_name"
    ];

    readonly_fields.forEach(field => {
        frm.set_df_property(field, "read_only", 1);
    });

    frm.refresh_fields();
}

// Make child table rows non-editable and images open in new tab
function make_images_clickable(frm) {
    const child_table_field = "car_repair_images";
    const image_field = "image";

    const grid = frm.fields_dict[child_table_field]?.grid;
    if (!grid) return;

    // Make all fields in child table read-only
    Object.keys(grid.fields_dict).forEach(f => {
        grid.fields_dict[f].df.read_only = 1;
    });

    // Prevent row editor from opening when clicking anywhere in the row
    grid.wrapper.off('click', '.grid-row').on('click', '.grid-row', function(e) {
        const target = $(e.target);
        // Only allow normal row click if it's NOT an image
        if (target.is('img') || target.closest('img').length) {
            e.stopPropagation();
        }
    });

    // Function to attach click to image
    const attach_image_click = () => {
        grid.grid_rows.forEach(row => {
            const img_cell = $(row.row).find(`[data-fieldname='${image_field}'] img`);
            if (img_cell.length && !img_cell.hasClass('click-handler')) {
                img_cell.addClass('click-handler');
                img_cell.css("cursor", "pointer");
                img_cell.off('click').on('click', function(e) {
                    e.stopPropagation(); // prevent row editor
                    const image_url = $(this).attr("src");
                    if (image_url) {
                        window.open(image_url, "_blank"); // open directly in new tab
                    }
                });
            }
        });
    };

    attach_image_click();
    grid.wrapper.on('grid-rendered', attach_image_click);
    grid.refresh();
}

