function make_images_clickable(frm) {
    frm.fields_dict["car_repair_images"].grid.wrapper
        .find('.grid-row')
        .each(function() {
            let $row = $(this);
            let data = $row.data('doc');

            if (data && data.image) {
                let cell = $row.find('div[data-fieldname="image"]');

                // Prevent row from going into edit mode
                cell.off('click');
                cell.css('cursor', 'pointer');

                cell.on('click', function(e) {
                    e.preventDefault();
                    e.stopPropagation(); // Stop opening edit dialog
                    window.open(data.image, "_blank"); // Open new tab
                });
            }
        });
}
